#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int load_numbers(const char *path, int **out, size_t *count)
{
    int status = 0;
    int *items = NULL;
    size_t used = 0, capacity = 0;
    char line[128];

    FILE *f = fopen(path, "r");
    if (f == NULL)
    {
        status = -1;
        goto done;
    }

    while (fgets(line, sizeof line, f) != NULL)
    {
        char *start = line;
        while (*start == ' ' || *start == '\t') start++;
        if (*start == '\n' || *start == '\r' || *start == '\0') continue;

        char *end;
        errno = 0;
        long v = strtol(start, &end, 10);
        while (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n') end++;
        if (end == start || *end != '\0' || errno == ERANGE || v < -2147483647L - 1 || v > 2147483647L)
        {
            status = -2;
            goto close_file;
        }

        if (used == capacity)
        {
            size_t bigger = capacity ? capacity * 2 : 8;
            int *grown = realloc(items, bigger * sizeof *grown);
            if (grown == NULL)
            {
                status = -3;
                goto close_file;
            }
            items = grown;
            capacity = bigger;
        }
        items[used++] = (int)v;
    }

    *out = items;
    *count = used;
    items = NULL;               /* handed to the caller */

close_file:
    fclose(f);
done:
    free(items);
    return status;
}

