TEST("reading numbers") { const char *path = "xenon_numbers_test.txt"; FILE *f = fopen(path, "w"); fputs("3
  -17

42  
", f); fclose(f); int *v = (int *)0x1; size_t n = 99; CHECK_EQ(load_numbers(path, &v, &n), 0); CHECK_EQ((int)n, 3); CHECK_EQ(v[0], 3); CHECK_EQ(v[1], -17); CHECK_EQ(v[2], 42); free(v); remove(path); }
TEST("many numbers grow the array") { const char *path = "xenon_numbers_many.txt"; FILE *f = fopen(path, "w"); for (int i = 0; i < 1000; i++) fprintf(f, "%d
", i * 3); fclose(f); int *v = NULL; size_t n = 0; CHECK_EQ(load_numbers(path, &v, &n), 0); CHECK_EQ((int)n, 1000); CHECK_EQ(v[999], 2997); free(v); remove(path); }
TEST("an empty file") { const char *path = "xenon_numbers_empty.txt"; FILE *f = fopen(path, "w"); fclose(f); int *v = (int *)0x1; size_t n = 99; CHECK_EQ(load_numbers(path, &v, &n), 0); CHECK(v == NULL); CHECK_EQ((int)n, 0); remove(path); }
TEST("failures leave the outputs alone") { const char *path = "xenon_numbers_bad.txt"; FILE *f = fopen(path, "w"); fputs("1
2
three
", f); fclose(f); int *v = (int *)0x1; size_t n = 99; CHECK_EQ(load_numbers(path, &v, &n), -2); CHECK(v == (int *)0x1); CHECK_EQ((int)n, 99); CHECK_EQ(load_numbers("no/such/dir/file.txt", &v, &n), -1); remove(path); }

